{
  "source_context": [
    {
      "section": "V1",
      "lyrics": [
        "あぁどうしようもないほどに",
        "私に蠢く獣",
        "水面浮かんで浮かんでは消えるあぶく"
      ]
    },
    {
      "section": "V2",
      "lyrics": [
        "あぁどうしようもなく悲しい",
        "私を動かす獣",
        "トートロジー握った手のあぶく"
      ]
    },
    {
      "section": "B1",
      "lyrics": [
        "過ぎ去る雲を思うより",
        "遥かへ遠吠え",
        "息継ぐ暇もないほど",
        "苦しいあれで"
      ]
    },
    {
      "section": "C1",
      "lyrics": [
        "悠々悠々夢を焼け",
        "魂の白い白い色で",
        "喜びの火に火をつけたいだけ",
        "想像は少しの泡銭",
        "冷めない言葉の両手で",
        "燃え尽きないものを数えて",
        "掬いたいだけ"
      ]
    }
  ],
  "section": "B1",
  "phrases": [
    {
      "id": "B1-01",
      "ja": "過ぎ去る雲を思うより",
      "budget": {
        "min": 10,
        "max": 10
      },
      "pattern": [
        4,
        3,
        3
      ]
    },
    {
      "id": "B1-02",
      "ja": "遥かへ遠吠え",
      "budget": {
        "min": 7,
        "max": 7
      },
      "pattern": [
        4,
        3
      ]
    },
    {
      "id": "B1-03",
      "ja": "息継ぐ暇もないほど",
      "budget": {
        "min": 10,
        "max": 10
      },
      "pattern": [
        4,
        3,
        3
      ]
    },
    {
      "id": "B1-04",
      "ja": "苦しいあれで",
      "budget": {
        "min": 6,
        "max": 6
      },
      "pattern": [
        3,
        3
      ]
    }
  ],
  "candidates": [
    {
      "label": "A",
      "phrases": [
        {
          "id": "B1-01",
          "zh": "与其空想着那过眼云烟"
        },
        {
          "id": "B1-02",
          "zh": "向着那远方长嚎"
        },
        {
          "id": "B1-03",
          "zh": "连喘息的那空隙都没有"
        },
        {
          "id": "B1-04",
          "zh": "这般痛苦难熬"
        }
      ]
    },
    {
      "label": "B",
      "phrases": [
        {
          "id": "B1-01",
          "zh": "比起追忆流逝的云"
        },
        {
          "id": "B1-02",
          "zh": "向遥远远方长嚎"
        },
        {
          "id": "B1-03",
          "zh": "连喘息的空隙都没有"
        },
        {
          "id": "B1-04",
          "zh": "那样痛苦啊"
        }
      ]
    },
    {
      "label": "C",
      "phrases": [
        {
          "id": "B1-01",
          "zh": "与其追忆那远去的流云"
        },
        {
          "id": "B1-02",
          "zh": "向天涯 长啸一声"
        },
        {
          "id": "B1-03",
          "zh": "连喘息都来不及的苦痛"
        },
        {
          "id": "B1-04",
          "zh": "灼烧着胸口"
        }
      ]
    },
    {
      "label": "D",
      "phrases": [
        {
          "id": "B1-01",
          "zh": "云飘远 就让它飘 我抬头"
        },
        {
          "id": "B1-02",
          "zh": "向远方 嘶吼一声"
        },
        {
          "id": "B1-03",
          "zh": "喉咙发烫 来不及 换口气"
        },
        {
          "id": "B1-04",
          "zh": "这痛 烙在胸口"
        }
      ]
    },
    {
      "label": "E",
      "phrases": [
        {
          "id": "B1-01",
          "zh": "不数流云 不回头 仰起头"
        },
        {
          "id": "B1-02",
          "zh": "向最远方 放声嚎"
        },
        {
          "id": "B1-03",
          "zh": "气没喘匀 喉咙紧 还想喊"
        },
        {
          "id": "B1-04",
          "zh": "那点痛 才痛快"
        }
      ]
    }
  ]
}

